-- Set backstop and defaults
declare self_checkpoint default (select timestamp("2024-01-01"));
declare partitions_to_update array<date>;
declare log_start_time default (select current_timestamp());

-- Get last run time for model *table_name* from INFORMATION_SCHEMA.PARTITIONS
-- (cached in _output_partition_history)
set self_checkpoint = (
    select timestamp("2024-01-01")
);

-- Find partitions from INFORMATION_SCHEMA.PARTITIONS (cached in _source_partition_history) 
-- that have updated since the last run time in the staging_table_name.
set partitions_to_update = (
  select
      array_agg(distinct parse_date('%Y%m%d', partition_id) ignore nulls)
  from `df-warehouse.propeller_dataform_template_sample_client._df_stg_partitions`
  where
      table_name = "stg_meta_ads_insights"
      -- Subtract 10 minutes to account for the runtime.  TODO log start time.
      and last_modified_time > timestamp_sub(self_checkpoint, interval 10 minute)
      and partition_id not in ("__NULL__")       
);


